package com.mercan.fuzulplanim.importer

import android.content.Context
import android.net.Uri
import com.mercan.fuzulplanim.data.*
import com.tom_roush.pdfbox.pdmodel.PDDocument
import com.tom_roush.pdfbox.text.PDFTextStripper
import org.xmlpull.v1.XmlPullParser
import org.xmlpull.v1.XmlPullParserFactory
import java.io.*
import java.nio.charset.StandardCharsets
import java.security.MessageDigest
import java.time.LocalDate
import java.time.YearMonth
import java.time.format.DateTimeFormatter
import java.time.format.DateTimeParseException
import java.util.Locale
import java.util.zip.ZipInputStream
import kotlin.math.abs

data class BudgetImportResult(val fixedExpenses:List<FixedExpenseEntity>,val installments:List<InstallmentEntity>,val months:List<MonthlyPlanEntity>,val contract:FuzulContractEntity?,val transactions:List<TransactionEntity>,val cards:List<CardEntity>,val summary:String)
data class ParsedStatementRow(val date:String,val description:String,val amount:Double,val category:String,val source:String,val raw:String="")
data class StatementPreview(val fileName:String,val fileType:String,val rows:List<ParsedStatementRow>,val note:String="")

object FileImportService {
    fun fileName(context:Context,uri:Uri):String{var name="dosya";context.contentResolver.query(uri,arrayOf(android.provider.OpenableColumns.DISPLAY_NAME),null,null,null)?.use{c->if(c.moveToFirst())name=c.getString(0)?:name};return name}
    fun readBytes(context:Context,uri:Uri):ByteArray=context.contentResolver.openInputStream(uri)?.use{it.readBytes()}?:error("Dosya açılamadı")
    fun importBudgetWorkbook(context:Context,uri:Uri):BudgetImportResult{val bytes=readBytes(context,uri);val xlsx=SimpleXlsx(bytes);val monthly=parseMonthlyPlan(xlsx.sheet("Aylık Plan"));val firstMonth=monthly.minByOrNull{it.month}?.month?:YearMonth.now().toString();val fixed=parseFixedExpenses(xlsx.sheet("SABIT_GİDER"),firstMonth);val inst=parseInstallments(xlsx.sheet("Taksit Takibi"));val contract=parseContract(xlsx.sheet("FUZUL_SOZLESME"));val tx=parseTransactions(xlsx.sheet("Tüm İşlemler"),fileName(context,uri));val cards=inst.map{it.bank}.filter{it.isNotBlank()}.distinct().map{CardEntity("xlsx-card-${hash(it).take(12)}",it,it)};if(monthly.isEmpty()&&fixed.isEmpty()&&contract==null)error("Bu dosya beklenen bütçe Excel yapısını içermiyor");return BudgetImportResult(fixed,inst,monthly,contract,tx,cards,"${fixed.size} sabit gider • ${inst.size} taksit • ${monthly.size} aylık plan • ${tx.size} işlem")}
    fun parseStatement(context:Context,uri:Uri):StatementPreview{val name=fileName(context,uri);val ext=name.substringAfterLast('.',"").lowercase(Locale.ROOT);val bytes=readBytes(context,uri);return when(ext){"xlsx"->parseGenericXlsx(name,bytes);"csv"->parseCsv(name,bytes.toString(StandardCharsets.UTF_8));"txt"->parseText(name,bytes.toString(StandardCharsets.UTF_8),"TXT");"pdf"->parsePdf(name,bytes);else->{val t=runCatching{bytes.toString(StandardCharsets.UTF_8)}.getOrDefault("");if(t.contains(";")||t.contains(","))parseCsv(name,t)else parseText(name,t,ext.uppercase())}}}
    fun toTransactions(p:StatementPreview,sourceOverride:String=""):List<TransactionEntity>=p.rows.map{r->val source=sourceOverride.ifBlank{r.source.ifBlank{p.fileName.substringBeforeLast('.')}};TransactionEntity(fingerprint(r.date,source,r.description,r.amount),r.date,source,r.description,r.amount,r.category,"",true,if(r.amount>=0)"INCOME" else "EXPENSE",p.fileName,r.raw.take(300))}

    private fun parseFixedExpenses(rows:List<List<String?>>,firstMonth:String):List<FixedExpenseEntity>{val out=mutableListOf<FixedExpenseEntity>();for(i in 1 until rows.size){val r=rows[i];val category=r.getOrNull(0).clean();val name=r.getOrNull(1).clean();val amount=r.getOrNull(2).num();val source=r.getOrNull(3).clean();if(category.isBlank()||name.isBlank()||amount==0.0)continue;val cl=category.lowercase(Locale("tr","TR"));val nl=name.lowercase(Locale("tr","TR"));if(cl.contains("bordro")||nl.contains("öz.sğl")||nl.contains("corolla club"))continue;val group=when{cl.contains("servis")||cl.contains("harç")->"education";cl.contains("kuaf")->"other";cl.contains("ulaş")||cl.contains("yakıt")->"transport";cl.contains("market")||cl.contains("giyim")||cl.contains("yeme")->"living";else->"bills"};out+=FixedExpenseEntity("xlsx-fixed-${hash("$category|$name|$source").take(20)}",name,category,amount,amount,source,group,"MONTHLY",firstMonth,"",1,false,0.0,true,true)};return out}
    private fun parseInstallments(rows:List<List<String?>>):List<InstallmentEntity>{val out=mutableListOf<InstallmentEntity>();for(i in 3 until rows.size){val r=rows[i];val bank=r.getOrNull(0).clean();if(bank.isBlank()||bank.contains("TOPLAM",true)||bank.contains("AYLIK",true))continue;val merchant=r.getOrNull(1).clean();val monthly=r.getOrNull(4).num();if(merchant.isBlank()||monthly==0.0)continue;val total=r.getOrNull(3).num();val totalN=r.getOrNull(5).num().toInt();val paid=r.getOrNull(6).num().toInt();val remaining=r.getOrNull(8).num();out+=InstallmentEntity("xlsx-inst-${hash("$bank|$merchant|$total|$monthly").take(22)}",bank,merchant,r.getOrNull(2).clean(),total,monthly,totalN,paid,remaining,excelMonth(r.getOrNull(9)),excelMonth(r.getOrNull(10)),true,true)};return out}
    private fun parseMonthlyPlan(rows:List<List<String?>>):List<MonthlyPlanEntity>{val out=mutableListOf<MonthlyPlanEntity>();for(i in 1 until rows.size){val r=rows[i];val month=excelMonth(r.getOrNull(1));if(month.isBlank())continue;val mete=r.getOrNull(2).num();val esma=r.getOrNull(3).num();if(mete==0.0&&esma==0.0&&r.getOrNull(15).num()==0.0)continue;out+=MonthlyPlanEntity(month,mete,esma,r.getOrNull(4).num(),r.getOrNull(6).num(),r.getOrNull(7).num(),r.getOrNull(8).num(),r.getOrNull(9).num(),r.getOrNull(10).num(),r.getOrNull(11).num(),r.getOrNull(12).num(),r.getOrNull(15).num())};return out}
    private fun parseContract(rows:List<List<String?>>):FuzulContractEntity?{if(rows.isEmpty())return null;val map=mutableMapOf<String,String>();for(r in rows){val k=r.getOrNull(0).clean();val v=r.getOrNull(1).clean();if(k.isNotBlank()&&v.isNotBlank())map[k.lowercase(Locale("tr","TR"))]=v};fun find(t:String)=map.entries.firstOrNull{it.key.contains(t)}?.value.orEmpty();val amount=find("sözleşme tutarı").num();if(amount==0.0)return null;val opening=rows.firstOrNull{it.getOrNull(5).clean().contains("Peşinat sonrası elde kalan",true)}?.getOrNull(6).num().takeIf{it!=0.0}?:rows.firstOrNull{it.getOrNull(5).clean().contains("Modelde kullanılan başlangıç devir",true)}?.getOrNull(6).num()?:0.0;return FuzulContractEntity(1,find("finansman türü"),amount,find("peşinat").num(),find("organizasyon ücreti").num(),excelDate(find("sözleşme tarihi")),find("tahsisat dönemi").num().toInt(),excelDate(find("tahsisat tarihi")),19,excelDate(find("son taksit tarihi")),opening)}
    private fun parseTransactions(rows:List<List<String?>>,sourceWorkbook:String):List<TransactionEntity>{if(rows.isEmpty())return emptyList();val out=mutableListOf<TransactionEntity>();for(i in 1 until rows.size){val r=rows[i];val date=excelDate(r.getOrNull(0).clean());val source=r.getOrNull(1).clean();val desc=r.getOrNull(2).clean();val amount=r.getOrNull(3).num();if(date.isBlank()||desc.isBlank()||amount==0.0)continue;out+=TransactionEntity(fingerprint(date,source,desc,amount),date,source,desc,amount,r.getOrNull(4).clean().ifBlank{classify(desc)},r.getOrNull(5).clean(),!r.getOrNull(6).clean().equals("Hayır",true),if(amount>=0)"INCOME" else "EXPENSE",r.getOrNull(10).clean().ifBlank{sourceWorkbook},r.getOrNull(11).clean())};return out}

    private fun parseGenericXlsx(name:String,bytes:ByteArray):StatementPreview{val x=SimpleXlsx(bytes);val sheetName=x.sheetNames().firstOrNull()?:error("Excel sayfası bulunamadı");return StatementPreview(name,"XLSX",parseTabularRows(x.sheet(sheetName),name.substringBeforeLast('.')),"Sayfa: $sheetName")}
    private fun parseCsv(name:String,text:String):StatementPreview{val lines=text.replace("\uFEFF","").lines().filter{it.isNotBlank()};if(lines.isEmpty())error("CSV boş");val d=listOf(';',',','\t').maxByOrNull{ch->lines.take(5).sumOf{it.count{c->c==ch}}}?:';';val rows=lines.map{parseDelimitedLine(it,d).map{v->v as String?}};return StatementPreview(name,"CSV",parseTabularRows(rows,name.substringBeforeLast('.')))}
    private fun parseText(name:String,text:String,type:String)=StatementPreview(name,type,parseLines(text.lines(),name.substringBeforeLast('.')),"Metin satırlarından ayrıştırıldı")
    private fun parsePdf(name:String,bytes:ByteArray):StatementPreview{val doc=PDDocument.load(ByteArrayInputStream(bytes));val text=doc.use{PDFTextStripper().getText(it)};if(text.isBlank())error("PDF metin içermiyor; taranmış görüntü olabilir");return StatementPreview(name,"PDF",parseLines(text.lines(),name.substringBeforeLast('.')),"Metin tabanlı PDF")}
    private fun parseTabularRows(rows:List<List<String?>>,defaultSource:String):List<ParsedStatementRow>{if(rows.isEmpty())return emptyList();var h=-1;var dc=-1;var desc=-1;var ac=-1;var debit=-1;var credit=-1;var src=-1;for(i in 0 until minOf(rows.size,25)){val c=rows[i].map{it.clean().lowercase(Locale("tr","TR"))};val d=c.indexOfFirst{it.contains("tarih")||it=="date"};val de=c.indexOfFirst{it.contains("açıklama")||it.contains("işlem")||it.contains("description")||it.contains("merchant")};val a=c.indexOfFirst{it=="tutar"||it.contains("işlem tutarı")||it.contains("amount")};val bo=c.indexOfFirst{it.contains("borç")||it.contains("debit")};val al=c.indexOfFirst{it.contains("alacak")||it.contains("credit")};val so=c.indexOfFirst{it.contains("kaynak")||it.contains("hesap")||it.contains("kart")};if(d>=0&&de>=0&&(a>=0||bo>=0||al>=0)){h=i;dc=d;desc=de;ac=a;debit=bo;credit=al;src=so;break}};if(h<0)return parseLines(rows.map{r->r.joinToString(" "){it.clean()}},defaultSource);val out=mutableListOf<ParsedStatementRow>();for(i in h+1 until rows.size){val r=rows[i];val date=parseDateFlexible(r.getOrNull(dc).clean());val description=r.getOrNull(desc).clean();if(date.isBlank()||description.isBlank())continue;val amount=if(ac>=0)money(r.getOrNull(ac).clean())else{val d=if(debit>=0)money(r.getOrNull(debit).clean())else 0.0;val c=if(credit>=0)money(r.getOrNull(credit).clean())else 0.0;if(c!=0.0)abs(c)else-abs(d)};if(amount==0.0)continue;val source=if(src>=0)r.getOrNull(src).clean()else defaultSource;out+=ParsedStatementRow(date,description,amount,classify(description),source.ifBlank{defaultSource},r.joinToString(" | "){it.clean()})};return out}
    private fun parseLines(lines:List<String>,defaultSource:String):List<ParsedStatementRow>{val dr=Regex("\\b(\\d{2}[./-]\\d{2}[./-](?:20)?\\d{2})\\b");val ar=Regex("[-+]?\\d{1,3}(?:[. ]\\d{3})*(?:,\\d{2})|[-+]?\\d+(?:[.,]\\d{2})");val out=mutableListOf<ParsedStatementRow>();for(line in lines){val dm=dr.find(line)?:continue;val date=parseDateFlexible(dm.groupValues[1]);if(date.isBlank())continue;val amounts=ar.findAll(line).map{it.value}.toList();if(amounts.isEmpty())continue;val raw=amounts.last();var amount=money(raw);if(amount==0.0)continue;val low=line.lowercase(Locale("tr","TR"));if(!raw.startsWith("-")&&(low.contains("harcama")||low.contains("ödeme")||low.contains("borç")||low.contains("alışveriş")))amount=-abs(amount);val desc=line.replace(dm.value,"").replace(raw,"").trim(' ','-','|',':');if(desc.length<2)continue;out+=ParsedStatementRow(date,desc,amount,classify(desc),defaultSource,line.take(500))};return out.distinctBy{"${it.date}|${it.description}|${it.amount}"}}
    private fun classify(description:String):String{val s=description.lowercase(Locale("tr","TR"));return when{listOf("migros","carrefour","a101","bim","şok","sok market","macrocenter").any{s.contains(it)}->"Market/Gıda";listOf("vodafone","turkcell","türk telekom","turk telekom","tt mobil").any{s.contains(it)}->"Ev/Faturalar - Telefon";listOf("turknet","kablo tv","türksat").any{s.contains(it)}->"Ev/Faturalar - İnternet";listOf("sepaş","enerjisa").any{s.contains(it)}->"Ev/Faturalar - Elektrik";listOf("aksa","akmercan","doğalgaz","dogalgaz").any{s.contains(it)}->"Ev/Faturalar - Doğalgaz";listOf("saski","su fatur").any{s.contains(it)}->"Ev/Faturalar - Su";listOf("hepsiburada","hepsipay","trendyol","amazon").any{s.contains(it)}->"E-Ticaret/Diğer";listOf("ets tur","etstur","otel","hotel").any{s.contains(it)}->"Seyahat/Tatil";listOf("mavi","mango","penti","bershka","özdilek","ozdilek","suwen").any{s.contains(it)}->"Giyim/Alışveriş";listOf("shell","opet","petrol ofisi","bp ","totalenergies").any{s.contains(it)}->"Ulaşım/Yakıt";listOf("netflix","spotify","google one","chatgpt","prime").any{s.contains(it)}->"Dijital Abonelik";else->"Diğer"}}
    private fun parseDelimitedLine(line:String,d:Char):List<String>{val out=mutableListOf<String>();val sb=StringBuilder();var q=false;var i=0;while(i<line.length){val c=line[i];if(c=='"'){if(q&&i+1<line.length&&line[i+1]=='"'){sb.append('"');i++}else q=!q}else if(c==d&&!q){out+=sb.toString().trim();sb.setLength(0)}else sb.append(c);i++};out+=sb.toString().trim();return out}
    private fun fingerprint(date:String,source:String,desc:String,amount:Double)=hash("$date|${source.lowercase()}|${desc.lowercase()}|${"%.2f".format(Locale.US,amount)}")
    private fun hash(s:String)=MessageDigest.getInstance("SHA-256").digest(s.toByteArray()).joinToString(""){"%02x".format(it)}
    private fun parseDateFlexible(raw:String):String{val s=raw.trim();if(s.matches(Regex("\\d+(?:\\.0+)?")))return excelDate(s);for(p in listOf("dd.MM.yyyy","dd/MM/yyyy","dd-MM-yyyy","yyyy-MM-dd","dd.MM.yy","dd/MM/yy"))try{return LocalDate.parse(s,DateTimeFormatter.ofPattern(p)).toString()}catch(_:DateTimeParseException){};return ""}
    private fun excelDate(raw:String):String{val n=raw.num();if(n<=0)return runCatching{LocalDate.parse(raw).toString()}.getOrDefault("");return LocalDate.of(1899,12,30).plusDays(n.toLong()).toString()}
    private fun excelMonth(raw:String?):String{val d=excelDate(raw.clean());return d.takeIf{it.length>=7}?.substring(0,7).orEmpty()}
    private fun money(s:String)=s.num()
}

private class SimpleXlsx(bytes:ByteArray){private val entries=mutableMapOf<String,ByteArray>();private val shared=mutableListOf<String>();private val sheets=linkedMapOf<String,String>();init{ZipInputStream(ByteArrayInputStream(bytes)).use{z->while(true){val e=z.nextEntry?:break;if(!e.isDirectory)entries[e.name]=z.readBytes();z.closeEntry()}};parseShared();parseWorkbook()};fun sheetNames()=sheets.keys.toList();fun sheet(name:String):List<List<String?>>{val p=sheets[name]?:return emptyList();return entries[p]?.let(::parseSheet)?:emptyList()};private fun parseShared(){val b=entries["xl/sharedStrings.xml"]?:return;val p=parser(b);var si=false;var t=false;val sb=StringBuilder();while(p.eventType!=XmlPullParser.END_DOCUMENT){when(p.eventType){XmlPullParser.START_TAG->when(p.name){"si"->{si=true;sb.setLength(0)};"t"->if(si)t=true};XmlPullParser.TEXT->if(si&&t)sb.append(p.text);XmlPullParser.END_TAG->when(p.name){"t"->t=false;"si"->{shared+=sb.toString();si=false}}};p.next()}};private fun parseWorkbook(){val rels=mutableMapOf<String,String>();entries["xl/_rels/workbook.xml.rels"]?.let{b->val p=parser(b);while(p.eventType!=XmlPullParser.END_DOCUMENT){if(p.eventType==XmlPullParser.START_TAG&&p.name=="Relationship"){val id=p.getAttributeValue(null,"Id").orEmpty();var target=p.getAttributeValue(null,"Target").orEmpty();if(target.startsWith("/"))target=target.removePrefix("/")else if(!target.startsWith("xl/"))target="xl/$target";rels[id]=target.replace("../","")};p.next()}};val b=entries["xl/workbook.xml"]?:return;val p=parser(b);while(p.eventType!=XmlPullParser.END_DOCUMENT){if(p.eventType==XmlPullParser.START_TAG&&p.name=="sheet"){val name=p.getAttributeValue(null,"name").orEmpty();val rid=(0 until p.attributeCount).firstNotNullOfOrNull{i->if(p.getAttributeName(i)=="id")p.getAttributeValue(i)else null}.orEmpty();rels[rid]?.let{sheets[name]=it}};p.next()}};private fun parseSheet(bytes:ByteArray):List<List<String?>>{val rows=mutableListOf<MutableList<String?>>();val p=parser(bytes);var ref="";var type="";var value:String?=null;var inv=false;var int=false;var inline=StringBuilder();fun ensure(r:Int,c:Int){while(rows.size<=r)rows.add(mutableListOf());while(rows[r].size<=c)rows[r].add(null)};while(p.eventType!=XmlPullParser.END_DOCUMENT){when(p.eventType){XmlPullParser.START_TAG->when(p.name){"c"->{ref=p.getAttributeValue(null,"r").orEmpty();type=p.getAttributeValue(null,"t").orEmpty();value=null;inline=StringBuilder()};"v"->inv=true;"t"->if(type=="inlineStr")int=true};XmlPullParser.TEXT->{if(inv)value=p.text;if(int)inline.append(p.text)};XmlPullParser.END_TAG->when(p.name){"v"->inv=false;"t"->int=false;"c"->{val(rc,cc)=refIndex(ref);ensure(rc,cc);val raw=if(type=="inlineStr")inline.toString()else value.orEmpty();rows[rc][cc]=when(type){"s"->raw.toIntOrNull()?.let{shared.getOrNull(it)}?:raw;"b"->if(raw=="1")"TRUE"else"FALSE";else->raw}}};p.next()};return rows};private fun parser(b:ByteArray)=XmlPullParserFactory.newInstance().newPullParser().apply{setInput(ByteArrayInputStream(b),"UTF-8")};private fun refIndex(ref:String):Pair<Int,Int>{val l=ref.takeWhile{it.isLetter()};val d=ref.dropWhile{it.isLetter()};var c=0;for(x in l.uppercase())c=c*26+(x-'A'+1);return(d.toIntOrNull()?.minus(1)?:0)to(c-1).coerceAtLeast(0)}}
private fun String?.clean()=this?.trim().orEmpty()
private fun String?.num():Double{val raw=this.clean();if(raw.isBlank())return 0.0;raw.toDoubleOrNull()?.let{return it};var s=raw.replace("₺","").replace("TL","",true).replace(" ","");if(s.contains(',')&&s.contains('.'))s=if(s.lastIndexOf(',')>s.lastIndexOf('.'))s.replace(".","").replace(',','.')else s.replace(",","")else if(s.contains(','))s=s.replace(',','.');return s.toDoubleOrNull()?:0.0}
